#pragma once

// The menu disk (Issues #38 and #40): a 720 x 128 ATR held in memory. Sectors 1
// to kMenuLoadSectors are the 6502 menu block generated by tools/make_menu.py,
// served as it is (the program asks the host for every screen); every other
// sector reads as zeros.

#include <array>
#include <cstddef>
#include <cstdint>

#include "rb/core/result.hpp"
#include "rb/core/span.hpp"
#include "rb/domain/image_byte_source.hpp"

namespace rb::host {

#include "menu_program.inc"

constexpr std::size_t kMenuHeaderSize = 16;
constexpr uint32_t kMenuSectors = 720;
constexpr uint32_t kMenuImageSize = kMenuHeaderSize + kMenuSectors * 128;

// Text to screen codes, left-aligned in `line`, padded with spaces. ATASCII
// 0x20-0x7E is kept; anything else is shown as '?'. screenLine() also shows
// lowercase letters in uppercase (file names); screenText() keeps them (server
// names, as in the reference).
void screenLine(const char* text, rb::core::Span<uint8_t> line) noexcept;
void screenText(const char* text, rb::core::Span<uint8_t> line) noexcept;

class MenuImage final : public rb::domain::ImageByteSource {
public:
    uint32_t size() const override { return kMenuImageSize; }
    rb::core::Result<void> readAt(uint32_t offset, rb::core::Span<uint8_t> out) override;

    // The loaded block as the Atari sees it (for tests).
    static rb::core::Span<const uint8_t> block() noexcept { return {kMenuBlock, sizeof kMenuBlock}; }
};

}  // namespace rb::host
